CREATE TABLE public.autonomy_grants(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, granted_by uuid NOT NULL, granted_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE TABLE public.autonomy_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 120), capabilities text[] NOT NULL CHECK (capabilities <@ ARRAY['summarize_account_activity','draft_checklist','review_sample_health','suggest_change_url']::text[] AND cardinality(capabilities) BETWEEN 1 AND 4), status text NOT NULL DEFAULT 'paused' CHECK (status IN ('paused','stopped','revoked')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.autonomy_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid, user_id uuid NOT NULL, actor_id uuid NOT NULL, event text NOT NULL, detail text NOT NULL DEFAULT '', occurred_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.autonomy_grants, public.autonomy_tasks, public.autonomy_events TO authenticated;
GRANT ALL ON public.autonomy_grants, public.autonomy_tasks, public.autonomy_events TO service_role;
ALTER TABLE public.autonomy_grants ENABLE ROW LEVEL SECURITY; ALTER TABLE public.autonomy_tasks ENABLE ROW LEVEL SECURITY; ALTER TABLE public.autonomy_events ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.autonomy_redact(input text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT left(regexp_replace(regexp_replace(regexp_replace(coalesce(input,''), '(?i)(password|passcode|pin|otp|token|secret|api[_-]?key|recovery|cvv|bearer)\s*[:=]?\s*\S+', '\1 [redacted]', 'g'), '[A-Za-z0-9_\-\.+/=]{24,}', '[redacted]', 'g'), '\m\d{6,}\M', '[redacted]', 'g'), 200) $$;
CREATE FUNCTION public.autonomy_authorized() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT public.account_session_active() AND (EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='owner' AND active) OR EXISTS(SELECT 1 FROM public.autonomy_grants WHERE user_id=auth.uid() AND revoked_at IS NULL)) $$;
REVOKE ALL ON FUNCTION public.autonomy_authorized() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.autonomy_authorized() TO authenticated;
CREATE POLICY grants_read ON public.autonomy_grants FOR SELECT TO authenticated USING ((user_id=auth.uid() AND public.account_session_active()) OR public.testing_owner());
CREATE POLICY tasks_read ON public.autonomy_tasks FOR SELECT TO authenticated USING (user_id=auth.uid() AND public.account_session_active());
CREATE POLICY events_read ON public.autonomy_events FOR SELECT TO authenticated USING (user_id=auth.uid() AND public.account_session_active());
CREATE FUNCTION public.set_autonomy_grant(target_user uuid, allowed boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT public.testing_owner() THEN RAISE EXCEPTION 'Owner required'; END IF; IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=target_user AND active AND role<>'owner') THEN RAISE EXCEPTION 'Member unavailable'; END IF;
 IF allowed THEN INSERT INTO public.autonomy_grants(user_id,granted_by) VALUES(target_user,auth.uid()) ON CONFLICT (user_id) DO UPDATE SET granted_by=auth.uid(),granted_at=now(),revoked_at=NULL;
 ELSE UPDATE public.autonomy_grants SET revoked_at=now() WHERE user_id=target_user; UPDATE public.autonomy_tasks SET status='revoked',updated_at=now() WHERE user_id=target_user AND status<>'revoked'; END IF;
 INSERT INTO public.autonomy_events(user_id,actor_id,event) VALUES(target_user,auth.uid(),CASE WHEN allowed THEN 'autonomy_granted' ELSE 'autonomy_revoked' END);
 INSERT INTO public.testing_audit(actor_id,event,subject_id) VALUES(auth.uid(),CASE WHEN allowed THEN 'autonomy_granted' ELSE 'autonomy_revoked' END,target_user); END $$;
CREATE FUNCTION public.create_autonomy_task(task_title text, task_capabilities text[]) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE tid uuid; BEGIN IF NOT public.autonomy_authorized() THEN RAISE EXCEPTION 'Autonomy authorization required'; END IF;
 INSERT INTO public.autonomy_tasks(user_id,title,capabilities) VALUES(auth.uid(),public.autonomy_redact(btrim(task_title)),(SELECT array_agg(DISTINCT c) FROM unnest(task_capabilities) c)) RETURNING id INTO tid;
 INSERT INTO public.autonomy_events(task_id,user_id,actor_id,event,detail) VALUES(tid,auth.uid(),auth.uid(),'task_created',array_to_string(task_capabilities,', ')); RETURN tid; END $$;
CREATE FUNCTION public.set_autonomy_task_status(target_task uuid, new_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT public.account_session_active() OR new_status NOT IN ('paused','stopped','revoked') THEN RAISE EXCEPTION 'Not allowed'; END IF;
 UPDATE public.autonomy_tasks SET status=new_status,updated_at=now() WHERE id=target_task AND user_id=auth.uid() AND status<>'revoked' AND (status<>'stopped' OR new_status='revoked'); IF NOT FOUND THEN RAISE EXCEPTION 'Task unavailable'; END IF;
 INSERT INTO public.autonomy_events(task_id,user_id,actor_id,event) VALUES(target_task,auth.uid(),auth.uid(),'task_'||new_status); END $$;
REVOKE ALL ON FUNCTION public.set_autonomy_grant(uuid,boolean) FROM PUBLIC; REVOKE ALL ON FUNCTION public.create_autonomy_task(text,text[]) FROM PUBLIC; REVOKE ALL ON FUNCTION public.set_autonomy_task_status(uuid,text) FROM PUBLIC; REVOKE ALL ON FUNCTION public.autonomy_redact(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_autonomy_grant(uuid,boolean), public.create_autonomy_task(text,text[]), public.set_autonomy_task_status(uuid,text) TO authenticated;